import pyomo.environ as pyo

DATA = {
    "budget": 20000,
    "cost_per_ad": 1000,
    # For each magazine: list of (tier_width, exposures_per_ad)
    "tiers": {
        "IJ": [(6, 10000), (4, 3000), (5, 2500)],   # ads 1-6, 7-10, 11-15
        "FS": [(4, 8000), (8, 6000), (3, 2000)],    # ads 1-4, 5-12, 13-15
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets: magazines and, per magazine, tier indices
    model.MAG = pyo.Set(initialize=list(d["tiers"].keys()))
    model.TIER = pyo.Set(initialize=range(max(len(v) for v in d["tiers"].values())))

    # Valid (magazine, tier) combinations
    def valid_pairs_init(m):
        pairs = []
        for mag, tiers in d["tiers"].items():
            for t in range(len(tiers)):
                pairs.append((mag, t))
        return pairs

    model.PAIRS = pyo.Set(dimen=2, initialize=valid_pairs_init)

    # Helper lookups for widths and exposure rates
    def width(mag, tier):
        return d["tiers"][mag][tier][0]

    def exposure(mag, tier):
        return d["tiers"][mag][tier][1]

    # Variables: number of ads bought in each (magazine, tier) block
    def ads_bounds(m, mag, tier):
        return (0, width(mag, tier))

    model.ads = pyo.Var(
        model.PAIRS,
        domain=pyo.NonNegativeIntegers,
        bounds=ads_bounds,
    )

    # Objective: maximize total exposures
    def obj_rule(m):
        return sum(exposure(mag, tier) * m.ads[mag, tier] for (mag, tier) in m.PAIRS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Constraint: total advertising spend within budget
    def budget_rule(m):
        total_ads = sum(m.ads[mag, tier] for (mag, tier) in m.PAIRS)
        return d["cost_per_ad"] * total_ads <= d["budget"]

    model.budget_con = pyo.Constraint(rule=budget_rule)

    return model


