import pyomo.environ as pyo

DATA = {
    "cost_per_ad": 1000,          # $ per full-page ad in either magazine
    "budget": 20000,              # $ total advertising budget
    "blocks": ["IJ1", "IJ2", "IJ3", "IJ4", "FS1", "FS2", "FS3", "FS4"],
    "block_magazine": {
        "IJ1": "IJ", "IJ2": "IJ", "IJ3": "IJ", "IJ4": "IJ",
        "FS1": "FS", "FS2": "FS", "FS3": "FS", "FS4": "FS",
    },
    "block_exposure": {
        "IJ1": 10000, "IJ2": 3000, "IJ3": 2500, "IJ4": 0,
        "FS1": 8000,  "FS2": 6000, "FS3": 2000, "FS4": 0,
    },
    "block_capacity": {
        "IJ1": 6, "IJ2": 4, "IJ3": 5, "IJ4": 0,   # IJ: 6, 4, 5, then 0
        "FS1": 4, "FS2": 8, "FS3": 3, "FS4": 0,   # FS: 4, 8, 3, then 0
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Set of ad blocks (piecewise-constant exposure segments)
    model.B = pyo.Set(initialize=d["blocks"])

    # Variable: number of ads placed in each block, within its capacity.
    def x_bounds(m, b):
        return (0, d["block_capacity"][b])

    model.x = pyo.Var(model.B, domain=pyo.NonNegativeIntegers, bounds=x_bounds)

    # Objective: maximize total exposures.
    def obj_rule(m):
        return sum(d["block_exposure"][b] * m.x[b] for b in m.B)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Budget constraint: total ad cost must not exceed the budget (<=).
    def budget_rule(m):
        return d["cost_per_ad"] * sum(m.x[b] for b in m.B) <= d["budget"]

    model.budget = pyo.Constraint(rule=budget_rule)

    return model


